import{G as e,W as t,n,rt as r}from"./chunks/framework.OKfwtFe7.js";var i=JSON.parse(`{"title":"大泥球（Big Ball of Mud）","description":"","frontmatter":{},"headers":[],"relativePath":"anti-patterns/big-ball-of-mud.md","filePath":"anti-patterns/big-ball-of-mud.md","lastUpdated":0}`),a={name:`anti-patterns/big-ball-of-mud.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="大泥球-big-ball-of-mud" tabindex="-1">大泥球（Big Ball of Mud） <a class="header-anchor" href="#大泥球-big-ball-of-mud" aria-label="Permalink to “大泥球（Big Ball of Mud）”">​</a></h1><p>大泥球描述一个已经上线、能跑、但没有主线架构的系统：功能靠补丁摞上去，数据靠复制绕过去，没人能说清改一处会影响哪里。它出自 Foote 与 Yoder 在 PLoP 1997 的论文 [S8]，那篇论文的结论有点反直觉：多数系统最后都会变成这个样子，而且往往是因为这样交付最快。</p><h2 id="形态" tabindex="-1">形态 <a class="header-anchor" href="#形态" aria-label="Permalink to “形态”">​</a></h2><ol><li><strong>没有可描述的结构</strong>：问&quot;这个系统分几层&quot;，得到的回答是&quot;按文件夹看吧&quot;。</li><li><strong>重复是常态</strong>：同一段业务逻辑在两三个地方各有一份拷贝，改一份忘两份。</li><li><strong>数据有多个真身</strong>：同一批数据存在两张表加一份导出文件里，以哪份为准看时段。</li><li><strong>绕行通道比正门多</strong>：为了不碰核心代码，新功能走旁路接口、定时任务、手工脚本。</li><li><strong>改动靠人肉记忆</strong>：没人敢自动化回归，因为知道&quot;有一处特判&quot;，但说不出在哪。</li></ol><p>论文里给的判断标准是结果导向的：结构不重要，能不能被理解、能不能被改才重要。一个没有分层但团队能快速改对的系统，不算大泥球；有分层图但每次改都要同步改五处的，算。</p><h2 id="代价" tabindex="-1">代价 <a class="header-anchor" href="#代价" aria-label="Permalink to “代价”">​</a></h2><ul><li>上新需求的成本随时间线性上升：每个需求都要先花一半时间确认不会碰到别的地方。</li><li>修复引入新缺陷的比例高：没有回归保护，补丁之间的相互作用只能上线后发现。</li><li>关键人依赖：系统的不变式写在几个老员工脑子里，不在代码里。</li><li>改造预算越拖越大：越晚开始，越只能继续摞补丁。</li></ul><h2 id="成因" tabindex="-1">成因 <a class="header-anchor" href="#成因" aria-label="Permalink to “成因”">​</a></h2><p>论文记录的路径基本一致：</p><ol><li><strong>先交付再整理</strong>：演示版直接当正式版用，临时方案变成永久结构。</li><li><strong>复用的诱惑</strong>：为了省一次工，把新功能接到旧数据模型上，用视图和复制来遮掩不匹配。</li><li><strong>放弃整理</strong>：改一处要动十处时，团队选择绕过去，结构进一步碎裂。</li><li><strong>无害的放任</strong>：系统能跑，没人投诉，于是没人给&quot;整理&quot;立项。</li></ol><h2 id="走出来" tabindex="-1">走出来 <a class="header-anchor" href="#走出来" aria-label="Permalink to “走出来”">​</a></h2><p>论文给的策略是绞杀而非重写（Strangler 思路在后来的微服务实践里被反复引用 [S13]）：</p><ol><li><strong>圈边界</strong>：挑一条能独立运行的业务切片（一个页面、一条对账链路），把它的入口、数据、调用方列出来，其余不碰。</li><li><strong>立防腐</strong>：新代码与旧代码之间只通过一个明确的接口往来，旧的字段命名不许渗进新层，这一层就是限界上下的雏形 [S11]。</li><li><strong>搬家不改逻辑</strong>：先把逻辑原样搬进新结构，跑通并补上回归测试，再谈改写。搬家和改写混在一起会分不清回归是谁引入的。</li><li><strong>逐条切片收口</strong>：每条切片独立可停，切片之间互不依赖，做到第三条就可以按季度停下来只维持。</li><li><strong>给&quot;绕行通道&quot;设到期日</strong>：旁路接口与手工脚本登记造册，写明谁引入、什么时候删。</li></ol><p>不建议的做法是一次性重写：大泥球里那些没写下来的特判，重写时会被当成 bug 修掉，然后上线才发现是需求。</p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h2><p>同一件事在泥球里的写法和在切片里的写法：</p><div class="language-python line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">python</span><pre class="shiki github-dark" style="background-color:#24292e;color:#e1e4e8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#818e99;"># 泥球：三个入口各有一份对账逻辑，参数格式还不一样</span></span>
<span class="line"><span style="color:#F97583;">def</span><span style="color:#B392F0;"> reconcile_web</span><span style="color:#E1E4E8;">(user_id, date):</span></span>
<span class="line"><span style="color:#E1E4E8;">    rows </span><span style="color:#F97583;">=</span><span style="color:#E1E4E8;"> db.query(</span><span style="color:#F97583;">f</span><span style="color:#9ECBFF;">&quot;SELECT * FROM orders WHERE user=</span><span style="color:#79B8FF;">{</span><span style="color:#E1E4E8;">user_id</span><span style="color:#79B8FF;">}</span><span style="color:#9ECBFF;"> AND day=&#39;</span><span style="color:#79B8FF;">{</span><span style="color:#E1E4E8;">date</span><span style="color:#79B8FF;">}</span><span style="color:#9ECBFF;">&#39;&quot;</span><span style="color:#E1E4E8;">)</span></span>
<span class="line"><span style="color:#E1E4E8;">    paid </span><span style="color:#F97583;">=</span><span style="color:#79B8FF;"> sum</span><span style="color:#E1E4E8;">(r.amount </span><span style="color:#F97583;">for</span><span style="color:#E1E4E8;"> r </span><span style="color:#F97583;">in</span><span style="color:#E1E4E8;"> rows </span><span style="color:#F97583;">if</span><span style="color:#E1E4E8;"> r.status </span><span style="color:#F97583;">in</span><span style="color:#E1E4E8;"> (</span><span style="color:#9ECBFF;">&quot;paid&quot;</span><span style="color:#E1E4E8;">, </span><span style="color:#9ECBFF;">&quot;refunded&quot;</span><span style="color:#E1E4E8;">, </span><span style="color:#9ECBFF;">&quot;manual_ok&quot;</span><span style="color:#E1E4E8;">))</span></span>
<span class="line"><span style="color:#79B8FF;">    ...</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">def</span><span style="color:#B392F0;"> reconcile_job</span><span style="color:#E1E4E8;">(batch):           </span><span style="color:#818e99;"># 定时任务版本，状态判断多了一个分支</span></span>
<span class="line"><span style="color:#79B8FF;">    ...</span></span>
<span class="line"><span style="color:#F97583;">def</span><span style="color:#B392F0;"> reconcile_fix</span><span style="color:#E1E4E8;">():                </span><span style="color:#818e99;"># 手工修复脚本，又是第三份</span></span>
<span class="line"><span style="color:#79B8FF;">    ...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>切片版把不变式收进一处，入口只负责取数：</p><div class="language-python line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">python</span><pre class="shiki github-dark" style="background-color:#24292e;color:#e1e4e8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#F97583;">class</span><span style="color:#B392F0;"> Reconciliation</span><span style="color:#E1E4E8;">:</span></span>
<span class="line"><span style="color:#79B8FF;">    STATUSES</span><span style="color:#F97583;"> =</span><span style="color:#E1E4E8;"> (</span><span style="color:#9ECBFF;">&quot;paid&quot;</span><span style="color:#E1E4E8;">, </span><span style="color:#9ECBFF;">&quot;refunded&quot;</span><span style="color:#E1E4E8;">, </span><span style="color:#9ECBFF;">&quot;manual_ok&quot;</span><span style="color:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">    def</span><span style="color:#B392F0;"> net_amount</span><span style="color:#E1E4E8;">(self, orders) -&gt; </span><span style="color:#79B8FF;">float</span><span style="color:#E1E4E8;">:</span></span>
<span class="line"><span style="color:#F97583;">        return</span><span style="color:#79B8FF;"> sum</span><span style="color:#E1E4E8;">(o.amount </span><span style="color:#F97583;">for</span><span style="color:#E1E4E8;"> o </span><span style="color:#F97583;">in</span><span style="color:#E1E4E8;"> orders </span><span style="color:#F97583;">if</span><span style="color:#E1E4E8;"> o.status </span><span style="color:#F97583;">in</span><span style="color:#79B8FF;"> self</span><span style="color:#E1E4E8;">.</span><span style="color:#79B8FF;">STATUSES</span><span style="color:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">def</span><span style="color:#B392F0;"> reconcile_web</span><span style="color:#E1E4E8;">(user_id, date):</span></span>
<span class="line"><span style="color:#F97583;">    return</span><span style="color:#E1E4E8;"> Reconciliation().net_amount(fetch_orders(user_id, date))</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">def</span><span style="color:#B392F0;"> reconcile_job</span><span style="color:#E1E4E8;">(batch):</span></span>
<span class="line"><span style="color:#F97583;">    return</span><span style="color:#E1E4E8;"> Reconciliation().net_amount(fetch_orders_batch(batch))</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>三个入口仍各取各的数，但&quot;哪些状态算已结算&quot;只有一份。先做这一层收口，再谈把取数方式统一。</p><h2 id="相关篇目" tabindex="-1">相关篇目 <a class="header-anchor" href="#相关篇目" aria-label="Permalink to “相关篇目”">​</a></h2><ul><li><a href="/hello-design-patterns/anti-patterns/god-object">神对象</a>：类级别的失控，常是系统级失控的一部分。</li><li><a href="/hello-design-patterns/anti-patterns/spaghetti-code">意面代码</a>：控制流层面的失控。</li><li><a href="/hello-design-patterns/other/event-sourcing">事件溯源</a>：当&quot;以哪份数据为准&quot;是主要痛点时，把变更历史作为真身是出路之一。</li></ul><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to “来源”">​</a></h2><ul><li>[S8] Brian Foote、Joseph Yoder，《Big Ball of Mud》，PLoP 1997。</li><li>[S11] Eric Evans，《Domain-Driven Design》，2003，限界上下文与防腐层。</li><li>[S13] Chris Richardson，《Microservices Patterns》，2018，绞杀式迁移的实践来源。</li></ul>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};